package net.officefloor.hq.app.claim;

import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.person.Person;
import net.officefloor.plugin.variable.Val;
import org.springframework.web.bind.annotation.RequestParam;

/** Records the claim just added; runs only once the add has passed every rule. */
public class AuditClaimAdded {
    public void audit(@Val Claim claim, @Val Person person, @RequestParam("user") String user, Audit audit) {
        audit.record("CLAIM_ADDED sheet=" + claim.sheetId() + " by=" + user + " person=" + person.name()
                + " amount=" + claim.amount().setScale(2).toPlainString() + " date=" + claim.date());
    }
}
-- Where a claim is listed among its person's: newest (highest) first. A new claim takes the next value; a claim
-- moved to another person takes the next value again, so it is listed as its new person's newest claim.
CREATE SEQUENCE claim_listed_seq START WITH 1;
ALTER TABLE claim ADD COLUMN listed BIGINT DEFAULT NEXT VALUE FOR claim_listed_seq NOT NULL;
CREATE INDEX claim_sheet_listed ON claim (sheet_id, listed);
-- A correction (a claim with a negative amount) names, by number, the settled claim of the same person it
-- corrects; null for any other claim.
ALTER TABLE claim ADD COLUMN corrects INT;
-- A person's statement records their due-total at that moment and binds each of their counting
-- claims to the figure it has then. The person keeps how many statements were taken, the last one's
-- due-total ('n/a' when it had none) and the sheet's today when it was taken.
ALTER TABLE person ADD COLUMN statement_count INT DEFAULT 0 NOT NULL;
ALTER TABLE person ADD COLUMN stated_total VARCHAR(30);
ALTER TABLE person ADD COLUMN statement_date DATE;
-- A stated claim shows and totals its bound figure (stated_due; null: n/a) until its person's next
-- statement rebinds it, or unbinds it (live again) when it no longer counts.
ALTER TABLE claim ADD COLUMN stated BOOLEAN DEFAULT FALSE NOT NULL;
ALTER TABLE claim ADD COLUMN stated_due DECIMAL(25, 2);
